@keyframes sya-input-value-error-feedback {
  0%, 100% { transform: translateX(0); }
  25% { transform: translateX(-4px); }
  50% { transform: translateX(3px); }
  75% { transform: translateX(-2px); }
}

@keyframes sya-input-value-error-feedback-reduced {
  0%, 100% { opacity: 1; }
  50% { opacity: 0.55; }
}

@keyframes sya-input-character-reveal {
  from { opacity: 0; transform: translateY(100%); }
  to { opacity: 1; transform: translateY(0%); }
}

export const motionTokens = {
  duration: {
    instant: 0.12,
    fast: 0.16,
    standard: 0.24,
    considered: 0.48,
    reveal: 0.6,
    lineReveal: 0.86,
  },
  ease: {
    enter: [0.16, 1, 0.3, 1],
    standard: [0.22, 1, 0.36, 1],
  },
  spring: {
    snappy: { type: "spring", visualDuration: 0.26, bounce: 0.12 },
    smooth: { type: "spring", visualDuration: 0.4, bounce: 0 },
    morph: { type: "spring", visualDuration: 0.42, bounce: 0.16 },
  },
  stagger: { item: 0.035, character: 0.025, word: 0.075, line: 0.08 },
  blur: { subtle: 2 },
} as const;

"use client";

import { forwardRef, type ComponentPropsWithoutRef, type ReactNode } from "react";
import { AnimatePresence, motion, useReducedMotion } from "motion/react";
import { IconMorph, type IconMorphPaths } from "../icon-morph/icon-morph";
import { motionTokens } from "../lib/motion-tokens";
import { MorphingText } from "../morphing-text/morphing-text";
import "../foundation.css";

export type ButtonVariant = "filled" | "bordered" | "text";
export type ButtonTone = "primary" | "secondary" | "success" | "warning" | "danger";
export type ButtonSize = "small" | "medium" | "large";

const baseClass = "inline-flex w-fit items-center justify-center gap-2 whitespace-nowrap rounded-[18px] border font-[inherit] font-[650] leading-none no-underline transition-[opacity,background-color,border-color,color,transform] duration-[var(--duration-fast)] ease-[var(--ease-standard)] [webkit-tap-highlight-color:transparent] focus-visible:outline-2 focus-visible:outline-[var(--focus)] focus-visible:outline-offset-3 disabled:cursor-not-allowed disabled:opacity-[0.48] aria-disabled:cursor-not-allowed aria-disabled:opacity-[0.48] active:not-disabled:translate-y-px";

const sizeClasses: Record<ButtonSize, string> = {
  small: "min-h-10 px-4 text-xs",
  medium: "min-h-[46px] px-5 text-[13px]",
  large: "min-h-[52px] px-6 text-sm",
};

const appearanceClasses: Record<ButtonVariant, Record<ButtonTone, string>> = {
  filled: {
    primary: "border-transparent bg-[var(--primary)] text-[var(--primary-foreground)] hover:bg-[var(--primary-hover)]",
    secondary: "border-transparent bg-[var(--surface-muted)] text-[var(--text)] hover:bg-[color-mix(in_srgb,var(--surface-muted)_82%,var(--text))]",
    success: "border-transparent bg-[var(--surface-muted)] text-[var(--success-surface-foreground)] hover:bg-[var(--success-surface)]",
    warning: "border-transparent bg-[var(--surface-muted)] text-[var(--warning-surface-foreground)] hover:bg-[var(--warning-surface)]",
    danger: "border-transparent bg-[var(--surface-muted)] text-[var(--danger-surface-foreground)] hover:bg-[var(--danger-surface)]",
  },
  bordered: {
    primary: "border-[color-mix(in_srgb,var(--text)_75%,transparent)] bg-[color-mix(in_srgb,var(--surface-muted)_75%,transparent)] text-[var(--text)] hover:border-[var(--text)] hover:bg-[color-mix(in_srgb,var(--primary)_25%,transparent)]",
    secondary: "border-[color-mix(in_srgb,var(--text-secondary)_72%,transparent)] bg-[color-mix(in_srgb,var(--surface-muted)_75%,transparent)] text-[var(--text-secondary)] hover:border-[var(--text-secondary)] hover:bg-[var(--surface-muted)] hover:text-[var(--text)]",
    success: "border-[var(--border)] bg-[color-mix(in_srgb,var(--surface-muted)_25%,transparent)] text-[var(--success-surface-foreground)] hover:border-[var(--success-surface-foreground)] hover:bg-[var(--success-surface)]",
    warning: "border-[var(--border)] bg-[color-mix(in_srgb,var(--surface-muted)_25%,transparent)] text-[var(--warning-surface-foreground)] hover:border-[var(--warning-surface-foreground)] hover:bg-[var(--warning-surface)]",
    danger: "border-[var(--border)] bg-[color-mix(in_srgb,var(--surface-muted)_25%,transparent)] text-[var(--danger-surface-foreground)] hover:border-[var(--danger-surface-foreground)] hover:bg-[var(--danger-surface)]",
  },
  text: {
    primary: "border-transparent bg-transparent text-[var(--text)] hover:bg-[var(--surface-muted)]",
    secondary: "border-transparent bg-transparent text-[var(--text-secondary)] hover:bg-[var(--surface-muted)] hover:text-[var(--text)]",
    success: "border-transparent bg-transparent text-[var(--success-surface-foreground)] hover:bg-[var(--surface-muted)]",
    warning: "border-transparent bg-transparent text-[var(--warning-surface-foreground)] hover:bg-[var(--surface-muted)]",
    danger: "border-transparent bg-transparent text-[var(--danger-surface-foreground)] hover:bg-[var(--surface-muted)]",
  },
};

function classes(variant: ButtonVariant, tone: ButtonTone, size: ButtonSize, className?: string) {
  return [baseClass, sizeClasses[size], appearanceClasses[variant][tone], className]
    .filter(Boolean)
    .join(" ");
}

interface ButtonStyleProps {
  variant?: ButtonVariant;
  tone?: ButtonTone;
  size?: ButtonSize;
}

type OneOrMany<Value> = Value | readonly Value[];

export interface ButtonProps
  extends Omit<ComponentPropsWithoutRef<"button">, "children"> {
  variant?: ButtonVariant;
  tone?: OneOrMany<ButtonTone>;
  size?: ButtonSize;
  children?: ReactNode;
  label?: OneOrMany<string>;
  icon?: OneOrMany<ReactNode>;
  iconPosition?: "start" | "end";
  loading?: OneOrMany<boolean>;
  state?: number;
  iconPaths?: IconMorphPaths;
}

function atState<Value>(value: OneOrMany<Value> | undefined, state: number) {
  if (value === undefined) return undefined;
  if (!Array.isArray(value)) return value as Value;
  return value[Math.min(state, value.length - 1)];
}

function ButtonIcon({ icons, state, paths, spinning }: {
  icons: OneOrMany<ReactNode>;
  state: number;
  paths?: IconMorphPaths;
  spinning?: boolean;
}) {
  const reduceMotion = useReducedMotion() ?? false;
  const values = Array.isArray(icons) ? icons : [icons];
  const current = values[Math.min(state, values.length - 1)];

  if (paths && values.length === 2) {
    return <IconMorph state={state > 0} from={values[0]} to={values[1]} paths={paths} size={18} />;
  }

  return (
    <span className="relative inline-grid size-[18px] place-items-center">
      <AnimatePresence initial={false} mode="popLayout">
        <motion.span
          className="absolute inset-0 grid origin-center place-items-center"
          key={state}
          initial={{ opacity: 0, scale: reduceMotion ? 1 : 0.62 }}
          animate={{ opacity: 1, scale: 1 }}
          exit={{ opacity: 0, scale: reduceMotion ? 1 : 0.62 }}
          transition={reduceMotion ? { duration: 0 } : motionTokens.spring.smooth}
        >
          <motion.span
            className="grid place-items-center [&>svg]:size-[18px]"
            animate={{ rotate: spinning && !reduceMotion ? 360 : 0 }}
            transition={spinning && !reduceMotion
              ? { duration: 0.8, ease: "linear", repeat: Infinity }
              : { duration: 0 }}
          >
            {current}
          </motion.span>
        </motion.span>
      </AnimatePresence>
    </span>
  );
}

export const Button = forwardRef<HTMLButtonElement, ButtonProps>(function Button({
  variant = "filled",
  tone = "primary",
  size = "medium",
  label,
  icon,
  iconPosition = "start",
  loading = false,
  state = 0,
  iconPaths,
  className,
  children,
  type = "button",
  ...props
}, ref) {
  const activeState = Math.max(0, Math.floor(state));
  const activeTone = atState(tone, activeState) ?? "primary";
  const isLoading = atState(loading, activeState) ?? false;
  const activeIcon = icon
    ? <ButtonIcon icons={icon} state={activeState} paths={iconPaths} spinning={isLoading} />
    : undefined;
  const content = label === undefined
    ? children
    : <MorphingText value={atState(label, activeState) ?? ""} />;
  const iconOnly = activeIcon !== undefined && content == null;

  return (
    <button
      ref={ref}
      {...props}
      type={type}
      aria-busy={isLoading || undefined}
      className={classes(variant, activeTone, size, [
        iconOnly && { small: "w-10 px-0", medium: "w-[46px] px-0", large: "w-[52px] px-0" }[size],
        className,
      ].filter(Boolean).join(" "))}
    >
      {activeIcon && iconPosition === "start" ? <span className="grid shrink-0 place-items-center" aria-hidden="true">{activeIcon}</span> : null}
      {content}
      {activeIcon && iconPosition === "end" ? <span className="grid shrink-0 place-items-center" aria-hidden="true">{activeIcon}</span> : null}
    </button>
  );
});

export interface ButtonLinkProps extends ComponentPropsWithoutRef<"a">, ButtonStyleProps {
  icon?: ReactNode;
  iconPosition?: "start" | "end";
}

export function ButtonLink({
  variant = "filled",
  tone = "primary",
  size = "medium",
  icon,
  iconPosition = "start",
  className,
  children,
  ...props
}: ButtonLinkProps) {
  return (
    <a {...props} className={classes(variant, tone, size, className)}>
      {icon && iconPosition === "start" ? <span className="grid shrink-0 place-items-center [&>svg]:size-[18px]" aria-hidden="true">{icon}</span> : null}
      {children}
      {icon && iconPosition === "end" ? <span className="grid shrink-0 place-items-center [&>svg]:size-[18px]" aria-hidden="true">{icon}</span> : null}
    </a>
  );
}

"use client";

import { useEffect, useId, useLayoutEffect, useRef, useState, type KeyboardEvent, type ReactNode } from "react";
import { AnimatePresence, animate, motion, useMotionValue, useReducedMotion } from "motion/react";
import { Button } from "../button/button";
import { motionTokens } from "../lib/motion-tokens";
import "../foundation.css";

const MotionButton = motion.create(Button);

export interface DropdownMenuItem { value: string; label: ReactNode; icon?: ReactNode; disabled?: boolean; danger?: boolean; onSelect?: () => void; }
export type DropdownMenuTriggerContent = "text" | "icon-text" | "icon";
export type DropdownMenuVariant = "filled" | "bordered";
export interface DropdownMenuProps { label: ReactNode; ariaLabel?: string; icon?: ReactNode; triggerContent?: DropdownMenuTriggerContent; items: DropdownMenuItem[]; variant?: DropdownMenuVariant; align?: "start" | "center" | "end"; expandedWidth?: number; className?: string; }

export function DropdownMenu({ label, ariaLabel, icon, triggerContent = "icon-text", items, variant = "filled", align = "center", expandedWidth = 240, className }: DropdownMenuProps) {
  const [open, setOpen] = useState(false);
  const rootRef = useRef<HTMLDivElement>(null);
  const sizerRef = useRef<HTMLSpanElement>(null);
  const menuRef = useRef<HTMLDivElement>(null);
  const triggerRef = useRef<HTMLButtonElement>(null);
  const itemRefs = useRef<Array<HTMLButtonElement | null>>([]);
  const openRef = useRef(false);
  const measuredRef = useRef(false);
  const sizes = useRef({ closedWidth: 46, closedHeight: 46, openWidth: expandedWidth, openHeight: 46 });
  const width = useMotionValue(46);
  const height = useMotionValue(46);
  const rootWidth = useMotionValue(46);
  const menuId = useId();
  const reduceMotion = useReducedMotion() ?? false;

  useLayoutEffect(() => {
    const root = rootRef.current, sizer = sizerRef.current, menu = menuRef.current;
    if (!root || !sizer || !menu) return;
    const measure = () => {
      const previousClosedWidth = sizes.current.closedWidth;
      const closedWidth = sizer.offsetWidth;
      const closedHeight = sizer.offsetHeight;
      const openWidth = Math.max(closedWidth, expandedWidth);
      const openHeight = menu.scrollHeight + 2;
      sizes.current = { closedWidth, closedHeight, openWidth, openHeight };
      root.style.setProperty("--dropdown-closed-width", `${closedWidth}px`);
      root.style.setProperty("--dropdown-closed-height", `${closedHeight}px`);
      root.style.setProperty("--dropdown-open-width", `${openWidth}px`);

      if (!measuredRef.current) {
        measuredRef.current = true;
        rootWidth.jump(closedWidth);
        width.jump(closedWidth);
        height.jump(closedHeight);
      } else if (closedWidth !== previousClosedWidth) {
        if (reduceMotion) {
          rootWidth.jump(closedWidth);
          if (!openRef.current) width.jump(closedWidth);
        } else {
          animate(rootWidth, closedWidth, motionTokens.spring.smooth);
          if (!openRef.current) animate(width, closedWidth, motionTokens.spring.smooth);
        }
      }
    };
    measure();
    const observer = new ResizeObserver(measure);
    observer.observe(sizer); observer.observe(menu);
    return () => observer.disconnect();
  }, [expandedWidth, height, reduceMotion, rootWidth, width]);

  useLayoutEffect(() => {
    openRef.current = open;
    const target = sizes.current;
    const nextWidth = open ? target.openWidth : target.closedWidth;
    const nextHeight = open ? target.openHeight : target.closedHeight;
    if (reduceMotion) { width.jump(nextWidth); height.jump(nextHeight); }
    else {
      const spring = open ? motionTokens.spring.morph : motionTokens.spring.smooth;
      const widthControl = animate(width, nextWidth, spring);
      const heightControl = animate(height, nextHeight, spring);
      return () => { widthControl.stop(); heightControl.stop(); };
    }
  }, [height, open, reduceMotion, width]);

  useLayoutEffect(() => { if (open) itemRefs.current.find(item => item && !item.disabled)?.focus({ preventScroll: true }); }, [open]);
  useEffect(() => {
    if (!open) return;
    const close = (event: PointerEvent) => { if (!rootRef.current?.contains(event.target as Node)) setOpen(false); };
    document.addEventListener("pointerdown", close);
    return () => document.removeEventListener("pointerdown", close);
  }, [open]);

  const onMenuKeyDown = (event: KeyboardEvent<HTMLDivElement>) => {
    if (event.key === "Escape") { event.preventDefault(); setOpen(false); requestAnimationFrame(() => triggerRef.current?.focus()); return; }
    const enabled = itemRefs.current.filter((item): item is HTMLButtonElement => Boolean(item && !item.disabled));
    const current = enabled.indexOf(document.activeElement as HTMLButtonElement);
    if (event.key === "ArrowDown") { event.preventDefault(); enabled[(current + 1) % enabled.length]?.focus(); }
    if (event.key === "ArrowUp") { event.preventDefault(); enabled[(current - 1 + enabled.length) % enabled.length]?.focus(); }
    if (event.key === "Home") { event.preventDefault(); enabled[0]?.focus(); }
    if (event.key === "End") { event.preventDefault(); enabled.at(-1)?.focus(); }
  };

  const showIcon = triggerContent !== "text" && Boolean(icon);
  const showLabel = triggerContent !== "icon" || !icon;
  const iconOnly = triggerContent === "icon" && Boolean(icon);
  const hidden = reduceMotion ? { opacity: 0 } : { opacity: 0, scale: .88, filter: `blur(${motionTokens.blur.subtle}px)` };
  const position = {
    start: { surface: "left-0 origin-top-left", trigger: "left-0", menu: "left-0" },
    center: { surface: "left-1/2 -translate-x-1/2 origin-top", trigger: "left-1/2 -translate-x-1/2", menu: "left-1/2 -translate-x-1/2" },
    end: { surface: "right-0 origin-top-right", trigger: "right-0", menu: "right-0" },
  }[align];

  return <motion.div ref={rootRef} className={["relative z-0 inline-flex h-[46px] min-w-0 data-[open]:z-[100]", className].filter(Boolean).join(" ")} data-open={open || undefined} data-trigger-content={triggerContent} style={{ width: rootWidth }}>
    <span ref={sizerRef} className={["absolute inline-flex min-h-[46px] items-center gap-2 px-5 invisible whitespace-nowrap", iconOnly && "w-[46px] justify-center px-0"].filter(Boolean).join(" ")} aria-hidden="true">
      {showIcon ? icon : null}{showLabel ? <span>{label}</span> : null}
    </span>
    <motion.div className={[
      "absolute top-0 z-30 min-w-full overflow-hidden rounded-[18px] border text-[var(--text)] shadow-[var(--shadow-resting)] transition-[border-radius] duration-[320ms] ease-[var(--ease-standard)] data-[open]:rounded-[var(--radius-surface)]",
      variant === "filled" ? "border-transparent bg-[var(--surface-muted)]" : "border-[var(--border)] bg-[var(--surface)]",
      position.surface,
    ].join(" ")} data-open={open || undefined} data-variant={variant} style={{ width, height }}>
      <MotionButton ref={triggerRef} type="button" variant="text" tone="primary" size="medium" className={["absolute top-0 flex h-[var(--dropdown-closed-height)] w-[var(--dropdown-closed-width)] items-center justify-center gap-2 border-0 bg-transparent px-[19px] text-[13px] whitespace-nowrap [transform-origin:inherit] hover:bg-[var(--surface-muted)]", position.trigger].join(" ")} aria-expanded={open} aria-controls={menuId} {...(open ? { inert: true } : {})}
        aria-label={iconOnly ? ariaLabel ?? (typeof label === "string" ? label : undefined) : undefined}
        initial={false} animate={open ? hidden : { opacity: 1, scale: 1, filter: "blur(0px)" }}
        transition={reduceMotion ? { duration: .1 } : open ? { duration: .1 } : { duration: .18, ease: motionTokens.ease.enter, delay: .08 }}
        onClick={() => setOpen(true)}>
        <AnimatePresence initial={false} mode="popLayout">
          <motion.span
            className="inline-flex items-center justify-center gap-2 whitespace-nowrap"
            key={triggerContent}
            initial={reduceMotion ? { opacity: 0 } : { opacity: 0, transform: "scale(0.96)", filter: `blur(${motionTokens.blur.subtle}px)` }}
            animate={{ opacity: 1, transform: "scale(1)", filter: "blur(0px)" }}
            exit={reduceMotion ? { opacity: 0 } : { opacity: 0, transform: "scale(0.96)", filter: `blur(${motionTokens.blur.subtle}px)` }}
            transition={{ duration: reduceMotion ? .08 : .18, ease: motionTokens.ease.enter }}
          >
            {showIcon ? <span className="grid shrink-0 place-items-center [&>svg]:size-[17px]" aria-hidden="true">{icon}</span> : null}{showLabel ? <span>{label}</span> : null}
          </motion.span>
        </AnimatePresence>
      </MotionButton>
      <motion.div ref={menuRef} id={menuId} role="menu" className={["absolute top-0 grid w-[var(--dropdown-open-width)] [transform-origin:inherit]", position.menu].join(" ")} {...(!open ? { inert: true } : {})} aria-label={typeof label === "string" ? label : "Menu"} onKeyDown={onMenuKeyDown}
        initial={false} animate={open ? { opacity: 1, scale: 1, filter: "blur(0px)" } : { opacity: 0, scale: reduceMotion ? 1 : .97, filter: reduceMotion ? "blur(0px)" : `blur(${motionTokens.blur.subtle}px)` }}
        transition={reduceMotion ? { duration: .1 } : open ? { duration: .2, ease: motionTokens.ease.enter, delay: .1 } : { duration: .08 }}>
        {items.map((item, index) => <button ref={node => { itemRefs.current[index] = node; }} key={item.value} type="button" role="menuitem" className={[
          "flex min-h-[46px] items-center gap-2.5 border-0 bg-transparent px-6 py-2.5 text-left text-[13px] text-[var(--text)] outline-offset-[-2px] focus-visible:outline-2 focus-visible:outline-[var(--focus)] first:rounded-t-[calc(var(--radius-surface)-1px)] last:rounded-b-[calc(var(--radius-surface)-1px)] only:rounded-[calc(var(--radius-surface)-1px)] disabled:cursor-not-allowed disabled:opacity-45",
          variant === "filled" ? "hover:bg-[var(--surface)]" : "hover:bg-[var(--surface-muted)]",
          item.danger && "text-[var(--danger-surface-foreground)] hover:bg-[var(--danger-surface)]",
        ].filter(Boolean).join(" ")} disabled={item.disabled}
          onClick={() => { item.onSelect?.(); setOpen(false); }}>
          {item.icon ? <span className="grid shrink-0 place-items-center [&>svg]:size-[17px]" aria-hidden="true">{item.icon}</span> : null}<span>{item.label}</span>
        </button>)}
      </motion.div>
    </motion.div>
  </motion.div>;
}

"use client";

import type { CSSProperties, ReactNode } from "react";
import { motion, useReducedMotion } from "motion/react";
import { motionTokens } from "../lib/motion-tokens";
import "../foundation.css";

export interface IconMorphPaths {
  from: string[];
  to: string[];
}

export interface IconMorphProps {
  state: boolean;
  from: ReactNode;
  to: ReactNode;
  paths?: IconMorphPaths;
  size?: number;
  strokeWidth?: number;
  className?: string;
  style?: CSSProperties;
}

const pathCommands = (path: string) => path.match(/[a-z]/gi)?.join("") ?? "";
const pathValues = (path: string) =>
  path.match(/-?(?:\d*\.)?\d+(?:e[-+]?\d+)?/gi)?.length ?? 0;

function pathsCanMorph(paths?: IconMorphPaths) {
  if (!paths || paths.from.length === 0 || paths.from.length !== paths.to.length) {
    return false;
  }

  return paths.from.every(
    (path, index) =>
      pathCommands(path) === pathCommands(paths.to[index] ?? "") &&
      pathValues(path) === pathValues(paths.to[index] ?? ""),
  );
}

export const iconMorphPresets = {
  menuClose: {
    from: ["M4 7L20 7", "M4 12L20 12", "M4 17L20 17"],
    to: ["M6 6L18 18", "M12 12L12 12", "M18 6L6 18"],
  },
  plusCheck: {
    from: ["M12 5L12 19", "M5 12L19 12"],
    to: ["M5 13L10 18", "M10 18L19 7"],
  },
  playPause: {
    from: ["M7 5L12 8L12 16L7 19Z", "M12 8L19 12L12 16L12 8Z"],
    to: ["M7 5L11 5L11 19L7 19Z", "M14 5L18 5L18 19L14 19Z"],
  },
  chevron: {
    from: ["M6 9L12 15L18 9"],
    to: ["M9 6L15 12L9 18"],
  },
} satisfies Record<string, IconMorphPaths>;

export function IconMorph({
  state,
  from,
  to,
  paths,
  size = 24,
  strokeWidth = 1.75,
  className,
  style,
}: IconMorphProps) {
  const reduceMotion = useReducedMotion() ?? false;
  const canMorph = pathsCanMorph(paths);
  const rootStyle = {
    ...style,
    "--icon-morph-size": `${size}px`,
  } as CSSProperties;

  if (canMorph && paths) {
    return (
      <motion.svg
        className={["relative inline-grid size-[var(--icon-morph-size)] shrink-0 place-items-center align-middle text-[inherit]", className].filter(Boolean).join(" ")}
        style={rootStyle}
        viewBox="0 0 24 24"
        width={size}
        height={size}
        fill="none"
        stroke="currentColor"
        strokeWidth={strokeWidth}
        strokeLinecap="round"
        strokeLinejoin="round"
        aria-hidden="true"
        focusable="false"
      >
        {paths.from.map((path, index) => (
          <motion.path
            key={index}
            initial={false}
            animate={{ d: state ? paths.to[index] : path }}
            transition={reduceMotion ? { duration: 0 } : motionTokens.spring.smooth}
          />
        ))}
      </motion.svg>
    );
  }

  const hidden = {
    opacity: 0,
    scale: reduceMotion ? 1 : 0.62,
  };
  const visible = { opacity: 1, scale: 1 };
  const transition = reduceMotion
    ? { duration: 0 }
    : {
        scale: motionTokens.spring.smooth,
        opacity: {
          duration: motionTokens.duration.fast,
          ease: motionTokens.ease.standard,
        },
      };

  return (
    <span
      className={["relative inline-grid size-[var(--icon-morph-size)] shrink-0 place-items-center align-middle text-[inherit]", className].filter(Boolean).join(" ")}
      style={rootStyle}
      aria-hidden="true"
    >
      <motion.span
        className="absolute inset-0 grid origin-center place-items-center will-change-[transform,opacity] motion-reduce:will-change-auto [&>svg]:size-full"
        initial={false}
        animate={state ? hidden : visible}
        transition={transition}
      >
        {from}
      </motion.span>
      <motion.span
        className="absolute inset-0 grid origin-center place-items-center will-change-[transform,opacity] motion-reduce:will-change-auto [&>svg]:size-full"
        initial={false}
        animate={state ? visible : hidden}
        transition={transition}
      >
        {to}
      </motion.span>
    </span>
  );
}

"use client";

import { useLayoutEffect, useRef, useState } from "react";
import {
  animate,
  motion,
  useMotionValue,
  useReducedMotion,
  type HTMLMotionProps,
} from "motion/react";
import { motionTokens } from "../lib/motion-tokens";
import "../foundation.css";

type SpanProps = Omit<HTMLMotionProps<"span">, "children">;

export interface MorphingTextProps extends SpanProps {
  value: string;
}

interface TextDifference {
  prefix: string;
  previous: string;
  current: string;
  suffix: string;
}

function compareText(previous: string, current: string): TextDifference {
  const previousCharacters = Array.from(previous);
  const currentCharacters = Array.from(current);
  const sharedLength = Math.min(previousCharacters.length, currentCharacters.length);
  let prefixLength = 0;

  while (
    prefixLength < sharedLength &&
    previousCharacters[prefixLength] === currentCharacters[prefixLength]
  ) {
    prefixLength += 1;
  }

  let previousEnd = previousCharacters.length;
  let currentEnd = currentCharacters.length;

  while (
    previousEnd > prefixLength &&
    currentEnd > prefixLength &&
    previousCharacters[previousEnd - 1] === currentCharacters[currentEnd - 1]
  ) {
    previousEnd -= 1;
    currentEnd -= 1;
  }

  return {
    prefix: currentCharacters.slice(0, prefixLength).join(""),
    previous: previousCharacters.slice(prefixLength, previousEnd).join(""),
    current: currentCharacters.slice(prefixLength, currentEnd).join(""),
    suffix: currentCharacters.slice(currentEnd).join(""),
  };
}

export function MorphingText({
  value,
  className,
  style,
  ...props
}: MorphingTextProps) {
  const [change, setChange] = useState({ previous: value, current: value });
  const measureRef = useRef<HTMLSpanElement>(null);
  const firstMeasurement = useRef(true);
  const reduceMotion = useReducedMotion() ?? false;
  const width = useMotionValue(0);

  if (change.current !== value) {
    setChange({ previous: change.current, current: value });
  }

  const difference = compareText(change.previous, change.current);
  const changedText = difference.current;
  const hasChangedText = Boolean(difference.previous || changedText);

  useLayoutEffect(() => {
    const measure = measureRef.current;
    if (!measure) return;
    let stopAnimation = () => {};

    const resize = () => {
      const nextWidth = measure.getBoundingClientRect().width;
      stopAnimation();

      if (firstMeasurement.current || reduceMotion) {
        firstMeasurement.current = false;
        width.jump(nextWidth);
        return;
      }

      const controls = animate(width, nextWidth, motionTokens.spring.smooth);
      stopAnimation = () => controls.stop();
    };

    resize();
    const observer = new ResizeObserver(resize);
    observer.observe(measure);
    return () => {
      stopAnimation();
      observer.disconnect();
    };
  }, [changedText, reduceMotion, width]);

  return (
    <motion.span
      {...props}
      className={["relative inline-block whitespace-nowrap", className].filter(Boolean).join(" ")}
      style={style}
      aria-live="polite"
    >
      <span className="absolute size-px overflow-hidden [clip:rect(0,0,0,0)] [clip-path:inset(50%)] whitespace-nowrap">{value}</span>
      <span className="inline-flex items-baseline whitespace-nowrap" aria-hidden="true">
        <span className="whitespace-pre">{difference.prefix}</span>
        <motion.span className="relative inline-grid min-w-0 overflow-hidden text-start" style={{ width }}>
          {hasChangedText ? (
            <motion.span
              key={change.current}
              className="absolute top-0 left-0 flex w-max flex-col [line-height:inherit] will-change-transform"
              initial={{
                transform: reduceMotion ? "translateY(-50%)" : "translateY(0%)",
              }}
              animate={{ transform: "translateY(-50%)" }}
              transition={reduceMotion ? { duration: 0 } : motionTokens.spring.smooth}
            >
              <span className="block h-[1lh] whitespace-pre">
                {difference.previous || "\u00a0"}
              </span>
              <span className="block h-[1lh] whitespace-pre">{changedText || "\u00a0"}</span>
            </motion.span>
          ) : null}
          <span className="col-[1] row-[1] invisible inline-block justify-self-start whitespace-pre pointer-events-none">{changedText || "\u00a0"}</span>
          <span ref={measureRef} className="absolute invisible w-max whitespace-pre pointer-events-none">
            {changedText}
          </span>
        </motion.span>
        <span className="whitespace-pre">{difference.suffix}</span>
      </span>
    </motion.span>
  );
}
